    /\ wmono psegs m m' /\ mem_inv psegs m'
    /\ stk psegs m' lo (bv_unsigned sp)
    /\ rw_cells psegs m' (errno_addr tp) [C4 (rg_errno a errv)]
    /\ rw_cells psegs m' RPAGE_SIZE [C8 (Z_to_bv 64 4096)]
